begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(16);
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000010', true);
select set_config('request.jwt.claim.role', 'authenticated', true);
select lives_ok($$select public.postcard_create_shop('20000000-0000-4000-8000-000000000001','Postcard test shop','Test address','a7000000-0000-4000-8000-000000000001')$$, 'owner creates shop');
select lives_ok($$select public.postcard_create_shop('20000000-0000-4000-8000-000000000001','Postcard test shop','Test address','a7000000-0000-4000-8000-000000000001')$$, 'shop request retries safely');
select is((select count(*)::int from public.postcard_shops where id='a7000000-0000-4000-8000-000000000001'),1,'one shop after retry');
select matches(public.postcard_get_shop_code('20000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001'),'^[0-9]{4}$','shop has shared four-digit numeric activation code');
select throws_ok($$select * from private.postcard_shop_secrets$$,'42501',null,'secret table cannot be selected');
select lives_ok($$select public.postcard_create_batch('20000000-0000-4000-8000-000000000001','eid','Postcard test batch',3,'a7000000-0000-4000-8000-000000000002')$$,'owner reserves batch');
select lives_ok($$select public.postcard_create_batch('20000000-0000-4000-8000-000000000001','eid','Postcard test batch',3,'a7000000-0000-4000-8000-000000000002')$$,'batch request retries safely');
select is((select count(*)::int from public.postcard_cards where batch_id=(select id from public.postcard_batches where request_id='a7000000-0000-4000-8000-000000000002')),3,'exactly three cards after retry');
select lives_ok($$select public.postcard_move_cards('20000000-0000-4000-8000-000000000001','assign','a7000000-0000-4000-8000-000000000001',array(select c.id from public.postcard_cards c join public.postcard_batches b on b.id=c.batch_id where b.request_id='a7000000-0000-4000-8000-000000000002'),'a7000000-0000-4000-8000-000000000003')$$,'owner assigns batch to shop');
select lives_ok($$select public.postcard_move_cards('20000000-0000-4000-8000-000000000001','sell','a7000000-0000-4000-8000-000000000001',array(select c.id from public.postcard_cards c join public.postcard_batches b on b.id=c.batch_id where b.request_id='a7000000-0000-4000-8000-000000000002' and c.ordinal=1),'a7000000-0000-4000-8000-000000000004')$$,'owner records real sale');
select throws_ok($$select public.postcard_move_cards('20000000-0000-4000-8000-000000000001','return','a7000000-0000-4000-8000-000000000001',array(select c.id from public.postcard_cards c join public.postcard_batches b on b.id=c.batch_id where b.request_id='a7000000-0000-4000-8000-000000000002'),'a7000000-0000-4000-8000-000000000005')$$,'23514','Cards unavailable for this movement','mixed sold/unsold return rejected atomically');
select is((select count(*)::int from public.postcard_cards where shop_id='a7000000-0000-4000-8000-000000000001'),3,'failed return leaves all cards unchanged');
select throws_ok($$update public.postcard_cards set sold_at=null$$,'42501',null,'direct card writes denied');
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000012', true);
select throws_ok($$select public.postcard_get_shop_code('20000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001')$$,'42501','Postcard management access required','viewer cannot reveal code');
select throws_ok($$select public.postcard_create_batch('20000000-0000-4000-8000-000000000001','eid','Forbidden',1,'a7000000-0000-4000-8000-000000000006')$$,'42501','Postcard management access required','viewer cannot reserve batch');
reset role;
set local role anon;
select throws_ok($$select * from public.postcard_cards$$,'42501',null,'anonymous visitor cannot read stock');
select * from finish();
rollback;
